import numpy as np

def make_x(agent_col, ball_col, ball_row, prev_ball_row, prev_agent_col=None):
    if prev_agent_col is None:
        prev_agent_col = agent_col
    x = np.zeros((10, 10, 5), dtype=float)
    # wall border in obstacle channel
    x[0, :, 3] = 1
    x[9, :, 3] = 1
    x[:, 0, 3] = 1
    x[:, 9, 3] = 1
    # agent
    x[8, agent_col, 0] = 1
    # moving ball
    x[ball_row, ball_col, 1] = 1
    # previous frame: previous agent and previous ball
    x[8, prev_agent_col, 4] = 1
    x[prev_ball_row, ball_col, 4] = 1
    return x.flatten()

probes = []
meta = []
for agent_col in [2, 4, 7]:
    for ball_row in [6, 7]:
        for prev_ball_row in [ball_row - 1, ball_row + 1]:
            if prev_ball_row < 1 or prev_ball_row > 8:
                continue
            for ball_col in range(1, 9):
                probes.append(make_x(agent_col, ball_col, ball_row, prev_ball_row))
                meta.append((agent_col, ball_row, prev_ball_row, ball_col))

X = np.array(probes)
logits = forward(X)
logits_shift = logits - logits.max(axis=1, keepdims=True)
probs = np.exp(logits_shift)
probs = probs / probs.sum(axis=1, keepdims=True)
argmax = np.argmax(logits, axis=1)

meta_to_idx = {m: i for i, m in enumerate(meta)}

print("argmax sequences over ball columns 1..8:")
for agent_col in [2, 4, 7]:
    for ball_row in [6, 7]:
        for prev_ball_row in [ball_row - 1, ball_row + 1]:
            if prev_ball_row < 1 or prev_ball_row > 8:
                continue
            seq = []
