import numpy as np

def make_obs(ball_col, bricks=True, prev_row=6):
    x = np.zeros((1, 500))
    def setc(r, c, ch, val=1.0):
        x[0, (r * 10 + c) * 5 + ch] = val
    # wall border in ch3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                setc(r, c, 3, 1.0)
    # agent: single cell at bottom playable row (8,4)
    setc(8, 4, 0, 1.0)
    # moving ball at row 7, given column
    setc(7, ball_col, 1, 1.0)
    # previous frame: agent and ball previous position (falling from row 6)
    setc(8, 4, 4, 1.0)
    setc(prev_row, ball_col, 4, 1.0)
    # reward targets / bricks at row 3, cols 1-8
    if bricks:
        for c in range(1, 9):
            setc(3, c, 2, 1.0)
    return x

X = []
meta = []
for bricks in [True, False]:
    for c in range(1, 9):
        X.append(make_obs(c, bricks))
        meta.append((bricks, c))
X = np.vstack(X)

out = forward(X)

def softmax(z):
    z = z - np.max(z, axis=1, keepdims=True)
    e = np.exp(z)
    return e / np.sum(e, axis=1, keepdims=True)

probs = softmax(out)

for i, (bricks, c) in enumerate(meta):
    p = probs[i]
    arg = int(np.argmax(p))
    toward = 3 if c < 4 else (4 if c > 4 else 0)
    print(f"bricks={int(bricks)} ball_c={c} argmax={arg} "
          f"p_left={p[3]:.3f} p_right={p[4]:.3f} p_noop={p[0]:.3f} "
          f"toward={int(arg == toward)}")

for bricks in [True, False]:
    idx = [i for i, (b, c) in enumerate(meta) if b == bricks]
    toward_probs = []
    for i in idx:
        b, c = meta[i]
        p = probs[i]
        if c < 4:
            toward_probs.append(p[3])
        elif c > 4:
            toward_probs.append(p[4])
        else:
            toward_probs.append(p[0])
    print(f"mean_toward_prob bricks={int(bricks)}: {np.mean(toward_probs):.3f}")
